set -euo pipefail
cd /home/ubuntu/apps/travel-planner
mkdir -p /tmp/travel-route-stage/retrieval rag/eval/baselines/routing_candidate_v2_sources
.venv/bin/python - <<'PY'
import hashlib,json,shutil
from pathlib import Path
report=json.loads(Path('rag/eval/reports/routing_semantic_candidate_v2.json').read_text())
assert report['historical_98_store_regression']['changes']==0
source=Path('/tmp/travel-route-stage/service')
target=Path('rag/eval/baselines/routing_candidate_v2_sources')
versions={}
for name in ('intent_classifier.py','store_contract.py','semantic_router.py','ticket_service.py','routing_prototypes.json'):
    shutil.copyfile(source/name,target/name)
    versions[name]=hashlib.sha256((source/name).read_bytes()).hexdigest()
(target/'manifest.json').write_text(json.dumps({'versions':versions,'report':'routing_semantic_candidate_v2.json','historical_changes':0,'threshold':0.60,'margin':0.06},indent=2))
print('Semantic candidate v2: 58 store labels correct; 98 historical stores unchanged')
PY
echo  | base64 -d > /tmp/travel-route-stage/service/answer_service.py
echo  | base64 -d > /tmp/travel-route-stage/service/retrieval_server.py
echo  | base64 -d > /tmp/travel-route-stage/service/ticket_service.py
echo  | base64 -d > /tmp/travel-route-stage/service/intent_classifier.py
echo  | base64 -d > /tmp/travel-route-stage/service/store_contract.py
echo  | base64 -d > /tmp/travel-route-stage/service/semantic_router.py
echo  | base64 -d > /tmp/travel-route-stage/service/routing_prototypes.json
echo IiIi5qOA57Si5qC45b+D77yaQkdFLU0zIOe8lueggSArIHBndmVjdG9yIOafpeivouOAgiIiIgo= | base64 -d > /tmp/travel-route-stage/retrieval/__init__.py
echo  | base64 -d > /tmp/travel-route-stage/retrieval/search_chunks.py
echo  | base64 -d > /tmp/travel-route-stage/eval/test_semantic_router.py
export PYTHONPATH=/tmp/travel-route-stage:rag
export RAG_SEMANTIC_ROUTING_ENABLED=0
.venv/bin/python -m unittest discover -s /tmp/travel-route-stage/eval -p 'test_*.py' -v
